-- Sándalo Spa — Appointments seed
-- Depends on: services.sql, customers.sql
-- Staff: uses real staff already in the DB (do NOT re-insert)
-- Covers roughly Jan–May 2026 with 30 appointments across 10 customers
-- Safe to re-run: ON CONFLICT DO NOTHING

-- Real staff IDs used below:
--   Maria Mesa      71bfc7e2-4820-43e1-b3dd-ed95b37ff001
--   Cristina Molina 6e8e64dd-1ba7-4f16-aecf-e5321086a1ad
--   Sara Orrego     502bc1f2-7102-4eb2-9769-c92234925cc3

-- ── Staff ↔ Services ───────────────────────────────────────────────────────
-- Wire all three therapists to all services

INSERT INTO staff_services (id, client_id, staff_id, service_id)
SELECT
  gen_random_uuid(),
  '00000000-0000-0000-0000-000000000001',
  s.id,
  svc.id
FROM (
  VALUES
    ('71bfc7e2-4820-43e1-b3dd-ed95b37ff001'::uuid),
    ('6e8e64dd-1ba7-4f16-aecf-e5321086a1ad'::uuid),
    ('502bc1f2-7102-4eb2-9769-c92234925cc3'::uuid)
) AS s(id)
CROSS JOIN services svc
WHERE svc.client_id = '00000000-0000-0000-0000-000000000001'
ON CONFLICT (staff_id, service_id) DO NOTHING;

